function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Each menu category is a section with the user‑items‑list‑section class
  $('#sections section.page-section.user-items-list-section').each(function () {
    const $section = $(this);

    // --- Determine the section heading (category) -----------------------
    let section = null;
    const $sectTitle = $section.find('.list-section-title strong');
    if ($sectTitle.length) {
      section = cleanText($sectTitle.text());
    } else {
      // Fallback: read from the data‑current-context attribute if the DOM changes
      const ctxAttr = $section.find('.user-items-list').attr('data-current-context');
      if (ctxAttr) {
        try {
          const data = JSON.parse(ctxAttr);
          if (data && data.sectionTitle) {
            section = cleanText(data.sectionTitle);
          }
        } catch (_) { /* ignore malformed JSON */ }
      }
    }

    // --- Iterate over each menu item inside this section ----------------
    $section.find('.user-items-list-simple .list-item').each(function () {
      const $item = $(this);

      // ---- Dish name ---------------------------------------------------
      const $nameEl = $item.find('.list-item-content__title');
      const nameRaw = $nameEl.text();
      const name = cleanText(nameRaw);
      if (!name) return; // skip items without a name

      // ---- Description -------------------------------------------------
      const $descWrapper = $item.find('.list-item-content__description');
      let description = null;
      const $firstPara = $descWrapper.find('p').eq(0);
      if ($firstPara.length) {
        description = cleanText($firstPara.text());
      }

      // ---- Price -------------------------------------------------------
      let price = null;
      const $priceEl = $descWrapper.find('p strong');
      if ($priceEl.length) {
        price = parsePrice($priceEl.text());
      }

      // ---- Build item and deduplicate ----------------------------------
      const item = { section, name, description, price };
      const key = `${item.section}|||${item.name}|||${item.description}|||${item.price}`;
      if (!seen.has(key)) {
        seen.add(key);
        items.push(item);
      }
    });
  });

  return items;
}
```

